
/* Remove dark theme specifics — now using light modern palette */
::-webkit-scrollbar {
  width: 10px;
  background: #eaeefc;
}
::-webkit-scrollbar-thumb {
  background: #dde6f6;
  border-radius: 8px;
}
::-webkit-scrollbar-thumb:hover {
  background: #c3dafd;
}

/* Utility classes */
.text-secondary {
  color: var(--text-secondary);
}

.section-title {
  color: var(--primary);
  font-size: 1.36rem;
  font-weight: 700;
  padding-bottom: 2px;
  margin: 30px 0 0;
  letter-spacing: -0.5px;
}

.card {
  background: var(--secondary);
  border-radius: var(--card-radius);
  box-shadow: var(--card-shadow);
  padding: 2rem;
  color: var(--text-color);
}

a {
  color: var(--primary);
  text-decoration: underline;
  transition: color 0.17s;
}
a:hover {
  color: var(--accent);
  text-decoration: underline;
}

/* Accessibility focus ring for all interactive elements */
:focus-visible {
  outline: 2.5px solid var(--accent);
  outline-offset: 2px;
  z-index: 1000;
}

/* Responsive adjustments */
@media (max-width: 640px) {
  .container {
    padding: 0 8px;
  }
  .btn, .btn-large {
    min-width: 95px;
    font-size: 1.05rem;
    padding-left: 1.1em;
    padding-right: 1.1em;
  }
  .title {
    font-size: 1.5rem;
    margin-bottom: 12px;
  }
